samples.sql:
SELECT CDSCode
FROM frpm
WHERE (Enrollment (K-12) + Enrollment (Ages 5-17)) > 500;

SELECT COUNT(CDSCode) / 12 AS MonthlyAverageSchools
FROM schools
WHERE DOC = 52 AND County = 'Alameda' AND strftime('%Y', OpenDate) = '1980';

SELECT District
FROM schools
WHERE City = 'Fresno' AND Magnet = 0;

SELECT (SUM(CASE WHEN T1.status = 'A' THEN T1.amount ELSE 0 END) / SUM(T1.amount)) * 100 AS percentage_paid
FROM loan AS T1
JOIN account AS T2 ON T1.account_id = T2.account_id;

SELECT trans_id, account_id, date, type, operation, amount, balance, k_symbol, bank, account
FROM trans
WHERE operation = 'VYBER' AND account_id = 3356;

SELECT label FROM molecule WHERE molecule_id NOT IN (
    SELECT T1.molecule_id FROM molecule AS T1 INNER JOIN connected AS T2 ON T1.molecule_id = T2.molecule_id INNER JOIN atom AS T3 ON T2.atom_id = T3.atom_id WHERE T3.element = 'Sn'
)

SELECT ROUND(SUM(CASE WHEN T1.bond_type = '-' AND T2.label = '+' THEN 1 ELSE 0 END) * 100 / COUNT(T1.bond_id), 5) AS proportion
FROM bond AS T1
JOIN molecule AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT COUNT(molecule_id) AS total_carcinogenic_molecules
FROM molecule
WHERE molecule_id BETWEEN 'TR000' AND 'TR030' AND label = '+';

SELECT CAST(SUM(CASE WHEN T1.label = '+' AND T2.element = 'cl' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.molecule_id) AS percentage
FROM molecule AS T1
JOIN atom AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT SUM(CASE WHEN mtgoCode IS NOT NULL THEN 1 ELSE 0 END) = COUNT(*) AS appears_on_mtgo_online
FROM sets
WHERE name = 'Angel of Mercy';

SELECT DisplayName
FROM users
WHERE strftime('%Y', CreationDate) = '2011';

SELECT PostHistoryTypeId FROM postHistory WHERE PostId = 3720
UNION
SELECT COUNT(DISTINCT UserId) FROM comments WHERE PostId = 3720;

SELECT superhero_name, AVG(height_cm) AS average_height
FROM superhero
GROUP BY superhero_name;

SELECT publisher.publisher_name FROM superhero 
JOIN publisher ON superhero.publisher_id = publisher.id 
WHERE superhero.id = 38;

SELECT COUNT(T1.id) FROM superhero AS T1
JOIN alignment AS T2 ON T1.alignment_id = T2.id
WHERE T1.gender_id = 2 AND T2.id = 1;

SELECT T1.superhero_name FROM superhero AS T1
JOIN superhero_attribute AS T2 ON T1.id = T2.hero_id
WHERE T1.height_cm = (SELECT MAX(height_cm) FROM superhero);

SELECT COUNT(*) AS numberOfDriversNotFinished
FROM results
WHERE time IS NULL AND YEAR(date) = 2015 AND MONTH(date) = 11 AND DAY(date) = 29;

SELECT MAX(lat) AS max_latitude
FROM circuits
WHERE name IN ('Silverstone Circuit', 'Hockenheimring', 'Hungaroring');

SELECT AVG(year) AS average_races_per_year
FROM races
WHERE date BETWEEN '2000-01-01' AND '2010-12-31';

SELECT player_api_id
FROM Player_Attributes
WHERE overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);

SELECT AVG(height) AS average_height
FROM Player
WHERE birthday >= '1990-01-01 00:00:00' AND birthday < '1996-01-01 00:00:00';

SELECT AVG(long_shots) AS average_long_shots
FROM Player_Attributes
WHERE player_name = 'Ahmed Samir Farag';

SELECT player_name
FROM Player
WHERE SUBSTR(birthday, 1, 7) = '1970-10';

SELECT MAX(crossing) AS best_crossing_rating
FROM Player_Attributes
WHERE player_name IN ('Alexis', 'Ariel Borysiuk', 'Arouna Kone');

SELECT player_name
FROM Player
WHERE strftime('%Y', 'now') - strftime('%Y', birthday) >= 35;

SELECT CAST(COUNT(CASE WHEN T1.height < 180 AND T2.overall_rating > 70 THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(T1.id) AS percentage
FROM Player AS T1
JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id;

SELECT MIN(Description) AS First_Documented_Date, Diagnosis
FROM Patient
WHERE ID = 48473;

SELECT CAST(SUM(CASE WHEN T1.Symptoms LIKE '%thrombocytopenia%' THEN 1 ELSE 0 END) AS REAL) * 100 / SUM(CASE WHEN T1.Diagnosis LIKE '%SLE%' THEN 1 ELSE 0 END) AS Proportion
FROM Examination AS T1
JOIN Patient AS T2 ON T1.ID = T2.ID;

SELECT COUNT(DISTINCT T1.ID) 
FROM Examination AS T1 
WHERE T1.APTT > 45 AND T1.Thrombosis = 0;

SELECT (SUM(CASE WHEN T1.category = 'Parking' AND T2.event_name = 'November Speaker' THEN T1.amount ELSE 0 END)) * 100 / COUNT(T2.event_name) AS percentage
FROM budget AS T1
JOIN event AS T2 ON T1.link_to_event = T2.event_id;

SELECT (SUM(CASE WHEN T2.event_name = 'Yearly Kickoff' THEN T1.cost ELSE 0 END) / SUM(T1.cost)) * 100 AS yearly_kickoff_percentage
FROM expense AS T1
JOIN event AS T2 ON T1.link_to_event = T2.event_id;

SELECT CAST(SUM(CASE WHEN T2.remaining < 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.event_id) AS percentage_over_budget
FROM event AS T1
JOIN budget AS T2 ON T1.event_id = T2.link_to_event;

SELECT SUM(T1.Amount * T1.Price) / COUNT(T1.TransactionID) AS AverageTotalPrice
FROM transactions_1k AS T1
WHERE T1.Date LIKE '2012-01-%';
